sourceSnapshots.character-memory:lu:
{
  "schemaVersion": 1,
  "characterId": "lu",
  "lastUpdatedChapterRef": "chapter:chapter-003.md",
  "factsKnown": [
    {
      "id": "lu-initial",
      "summary": "知道自己没有换过钟芯；不知道慢了几分钟",
      "sourceChapterRef": "chapter:chapter-001.md"
    },
    {
      "id": "3121666b-d725-4365-a599-f1a0022dc27a",
      "summary": "听见船底闷响，观察到小艇断绳；没有碰药箱，苏砚未搜他。"
    }
  ],
  "emotionalMemory": [
    {
      "summary": "因被允许以克制证明自己而稍安，仍戒备被当替罪羊。",
      "id": "8d8a111f-cf86-4bc1-8ee0-684e2815b954"
    }
  ],
  "relationshipDeltas": [
    {
      "summary": "苏砚没有搜查使敌意稍缓；何芷未指责他。",
      "id": "15c798ee-db88-4e8f-987c-aee6a6e52ed8"
    }
  ],
  "unresolvedIntentions": [
    {
      "id": "lu-goal",
      "summary": "修好潮钟并洗清偷芯嫌疑"
    },
    {
      "summary": "找机会查船底异响，凭证据洗清偷芯嫌疑。",
      "id": "e3dfd827-00b9-488b-9eb5-d0e74ba13d87"
    }
  ],
  "privateMisbeliefs": []
}

sourceSnapshots.character-memory:ye:
{
  "schemaVersion": 1,
  "characterId": "ye",
  "lastUpdatedChapterRef": "chapter:chapter-003.md",
  "factsKnown": [
    {
      "id": "ye-initial",
      "summary": "知道低潮碎石滩危险、渡口至灯塔航程四十分钟；不知道暗格和七分钟",
      "sourceChapterRef": "chapter:chapter-001.md"
    },
    {
      "id": "bd720ed6-b0a1-43d1-aefe-47f31d4dcb95",
      "summary": "船底有闷响；雾中无灯艇带着断绳，船按正规航道避让；航程不可缩短。"
    }
  ],
  "emotionalMemory": [
    {
      "summary": "担心执照与船员责任，庆幸何芷采纳稳船而非催行。",
      "id": "bfae2a56-5b3c-4c50-b834-28342efb7326"
    }
  ],
  "relationshipDeltas": [
    {
      "summary": "何芷信任其操船得到印证；陆行舟没有擅碰船体。",
      "id": "9f3dfe72-d503-41c0-9c00-446d3fe919ad"
    }
  ],
  "unresolvedIntentions": [
    {
      "id": "ye-goal",
      "summary": "保住执照与船员"
    },
    {
      "summary": "安全驶抵灯塔，之后再判断船底异响原因。",
      "id": "e690ec52-6143-4116-ba63-3cf765c660dd"
    }
  ],
  "privateMisbeliefs": []
}

sourceSnapshots.character-memory:cen:
{
  "schemaVersion": 1,
  "characterId": "cen",
  "lastUpdatedChapterRef": "chapter:chapter-003.md",
  "factsKnown": [
    {
      "id": "cen-initial",
      "summary": "知道议事厅今夜要收走蓝签账页；不知道藏处，不知道密道口令",
      "sourceChapterRef": "chapter:chapter-001.md"
    },
    {
      "id": "79c52b8e-3dfe-445d-b192-27edaf2f181b",
      "summary": "他随船同行，听见何芷强调病人优先、账页暂不谈；听见众人议论无灯小艇与断绳，断绳成因未知。"
    }
  ],
  "emotionalMemory": [
    {
      "summary": "担忧旧账被公开，也因何芷拒绝让病人作筹码而短暂认同。",
      "id": "3bcd4180-6a87-4ebb-bf67-f9f1fff42c85"
    }
  ],
  "relationshipDeltas": [
    {
      "summary": "何芷坚持先送药，岑寂对她的试探未得回应；苏砚仍守程序。",
      "id": "2a0ceb9a-265b-451d-b7a5-290f61eee9dc"
    }
  ],
  "unresolvedIntentions": [
    {
      "id": "cen-goal",
      "summary": "阻止旧账公开但不伤及病人"
    },
    {
      "summary": "抵灯塔后推动先交公文，再处理账页；隐藏昨夜入钟楼事实。",
      "id": "9ecd35f6-723e-48fd-a7e0-e117b1d96ded"
    }
  ],
  "privateMisbeliefs": []
}

